INSERT INTO `seiko_books` VALUES (1, '深入理解计算机系统', 'Randal E. Bryant', 'https://picsum.photos/seed/book1/200/300', '从程序员视角全面剖析计算机系统的经典教材，涵盖数据表示、汇编、存储器层次、链接、异常控制流等核心内容。', 0, '2026-07-29 10:00:00', '2026-07-29 10:00:00', NULL);
INSERT INTO `seiko_books` VALUES (2, '设计模式：可复用面向对象软件的基础', 'Erich Gamma', 'https://picsum.photos/seed/book2/200/300', 'GoF 四人帮经典著作，23 种设计模式的权威指南，软件工程师必读。', 0, '2026-07-29 10:01:00', '2026-07-29 10:01:00', NULL);
INSERT INTO `seiko_books` VALUES (3, '代码整洁之道', 'Robert C. Martin', 'https://picsum.photos/seed/book3/200/300', '讲述编写可读、可维护代码的原则和实践，提升代码质量的必读书。', 0, '2026-07-29 10:02:00', '2026-07-29 10:02:00', NULL);
INSERT INTO `seiko_books` VALUES (4, '高性能 MySQL', 'Baron Schwartz', 'https://picsum.photos/seed/book4/200/300', 'MySQL 性能优化的百科全书，涵盖架构、索引、查询优化、复制、高可用等。', 0, '2026-08-01 09:00:00', '2026-08-01 09:00:00', NULL);
INSERT INTO `seiko_books` VALUES (5, '人类简史', '尤瓦尔·赫拉利', 'https://picsum.photos/seed/book5/200/300', '从认知革命到科学革命，重新审视人类的过去与未来，开阔视野的佳作。', 0, '2026-08-05 14:00:00', '2026-08-05 14:00:00', NULL);
INSERT INTO `seiko_books` VALUES (6, '活着', '余华', 'https://picsum.photos/seed/book6/200/300', '讲述一个人和他的命运之间的友情，一部感人至深的中国当代文学经典。', 0, '2026-08-10 16:00:00', '2026-08-10 16:00:00', NULL);
