INSERT INTO `seiko_logs` VALUES (73, 'operation', 'INFO', '查询公告列表', '', 2, 'seiko', '0:0:0:0:0:0:0:1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0', 'GET', 'com.seiko.blog.controller.manage.NoticeManageController.getNoticeList()', '/api/manage/notice/list', 'page=1&size=10', '{\"code\":200,\"message\":\"操作成功\",\"data\":{\"records\":[{\"id\":1,\"noticeTitle\":\"网站上线公告\",\"noticeContent\":\"Seiko Blog 正式上线啦！欢迎大家访问，后续会持续更新技术文章和生活随笔。\",\"noticeLink\":null,\"sortOrder\":1,\"enabled\":true,\"createTime\":\"2026-07-29 10:00:00\"},{\"id\":2,\"noticeTitle\":\"评论功能已开放\",\"noticeContent\":\"博客评论功能已开放，欢迎大家在文章下留言交流。\",\"noticeLink\":null,\"sortOrder\":2,\"enabled\":true,\"createTime\":\"2026-08-01 09:00:00\"},{\"id\":3,\"noticeTitle\":\"Java 21 新特性系列文章更新中\",\"noticeContent\":\"正在撰写 Java 21 新特性系列文章，包括虚拟线程、模式匹配等，敬请期待。\",\"noticeLink\":\"/posts/java-21-new-features\",\"sortOrder\":3,\"enabled\":true,\"createTime\":\"2026-08-05 14:00:00\"},{\"id\":4,\"noticeTitle\":\"系统维护通知\",\"noticeContent\":\"本周六凌晨 2:00-4:00 进行系统维护，期间网站可能无法访问，敬请谅解。\",\"noticeLink\":null,\"sortOrder\":4,\"enabled\":false,\"createTime\":\"2026-08-10 16:00:00\"},{\"id\":5,\"noticeTitle\":\"新增电影推荐板块\",\"noticeContent\":\"博客新增电影推荐板块，记录看过的好电影，欢迎交流。\",\"noticeLink\":\"/movies\",\"sortOrder\":5,\"enabled\":true,\"createTime\":\"2026-08-12 10:00:00\"}],\"total\":5,\"size\":10,\"current\":1,\"pages\":1},\"success\":true}', 200, 0, 19, NULL, 0, '2026-08-19 15:20:18', '2026-08-19 15:20:18', NULL);
