INSERT INTO `seiko_logs` VALUES (150, 'operation', 'INFO', '查询字典项选项', '', 2, 'seiko', '0:0:0:0:0:0:0:1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0', 'GET', 'com.seiko.blog.controller.manage.DictManageController.getItemOptions()', '/api/manage/dict/item/options', 'typeCode=movie_top', '{\"code\":200,\"message\":\"操作成功\",\"data\":[{\"id\":21,\"typeCode\":\"movie_top\",\"itemLabel\":\"普通\",\"itemValue\":\"0\",\"itemTag\":\"gray\",\"isDefault\":true,\"enabled\":true,\"sortOrder\":1,\"createTime\":\"2026-08-19 11:58:23\"},{\"id\":22,\"typeCode\":\"movie_top\",\"itemLabel\":\"置顶\",\"itemValue\":\"1\",\"itemTag\":\"yellow\",\"isDefault\":false,\"enabled\":true,\"sortOrder\":2,\"createTime\":\"2026-08-19 11:58:23\"}],\"success\":true}', 200, 0, 4, NULL, 0, '2026-08-21 11:42:14', '2026-08-21 11:42:14', NULL);
INSERT INTO `seiko_logs` VALUES (151, 'operation', 'INFO', '查询电影列表', '', 2, 'seiko', '0:0:0:0:0:0:0:1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0', 'GET', 'com.seiko.blog.controller.manage.MovieManageController.getMovieList()', '/api/manage/movie/list', 'page=1&size=10', '{\"code\":200,\"message\":\"操作成功\",\"data\":{\"records\":[{\"id\":5,\"movieName\":\"千与千寻\",\"isTop\":1,\"rating\":9.4,\"ratingSource\":\"豆瓣\",\"tags\":\"剧情,动画,奇幻\",\"synopsis\":\"千寻和爸爸妈妈一同驱车前往新家，在郊外的小路上不慎进入了神秘的隧道——他们去到了另外一个诡异世界—一个中世纪的小镇。\",\"backdrop\":\"https://picsum.photos/seed/movie5/1280/720\",\"duration\":125},{\"id\":2,\"movieName\":\"霸王别姬\",\"isTop\":1,\"rating\":9.6,\"ratingSource\":\"豆瓣\",\"tags\":\"剧情,爱情,同性\",\"synopsis\":\"段小楼与程蝶衣是一对打小一起长大的师兄弟，两人一个演生，一个饰旦，一向配合天衣无缝，尤其一出《霸王别姬》，更是誉满京城。\",\"backdrop\":\"https://picsum.photos/seed/movie2/1280/720\",\"duration\":171},{\"id\":1,\"movieName\":\"肖申克的救赎\",\"isTop\":1,\"rating\":9.7,\"ratingSource\":\"豆瓣\",\"tags\":\"剧情,犯罪,经典\",\"synopsis\":\"一场谋杀案使银行家安迪蒙冤入狱，谋杀妻子及其情人的指控将囚禁他终生。在肖申克监狱里，希望似乎虚无缥缈，终身监禁的惩罚无法挽回。\",\"backdrop\":\"https://picsum.photos/seed/movie1/1280/720\",\"duration\":142},{\"id\":8,\"movieName\":\"大话西游之大圣娶亲\",\"isTop\":0,\"rating\":9.2,\"ratingSource\":\"豆瓣\",\"tags\":\"喜剧,爱情,奇幻,古装\",\"synopsis\":\"至尊宝被月光宝盒带回到五百年前，遇见紫霞仙子，被对方拔出宝剑，一段感情就此展开。\",\"backdrop\":\"https://picsum.photos/seed/movie8/1280/720\",\"duration\":95},{\"id\":7,\"movieName\":\"星际穿越\",\"isTop\":0,\"rating\":9.4,\"ratingSource\":\"豆瓣\",\"tags\":\"剧情,科幻,冒险\",\"synopsis\":\"近未来的地球黄沙遍野，小麦、秋葵等基础农作物相继因枯萎病灭绝，人类不再像从前那样仰望星空，放纵想象力和灵感的迸发。\",\"backdrop\":\"https://picsum.photos/seed/movie7/1280/720\",\"duration\":169},{\"id\":6,\"movieName\":\"盗梦空间\",\"isTop\":0,\"rating\":9.3,\"ratingSource\":\"豆瓣\",\"tags\":\"剧情,科幻,悬疑\",\"synopsis\":\"道姆·柯布与同事阿瑟和纳什在一次针对日本能源大亨齐藤的盗梦行动中失败，反被齐藤利用。\",\"backdrop\":\"https://picsum.photos/seed/movie6/1280/720\",\"duration\":148},{\"id\":4,\"movieName\":\"泰坦尼克号\",\"isTop\":0,\"rating\":9.4,\"ratingSource\":\"豆瓣\",\"tags\":\"剧情,爱情,灾难\",\"synopsis\":\"1912年4月10日，号称 \\\"世界工业史上的奇迹\\\"的豪华客轮泰坦尼克号开始了自己的处女航，从英国的南安普顿出发驶往美国纽约。\",\"backdrop\":\"https://picsum.photos/seed/movie4/1280/720\",\"duration\":194},{\"id\":3,\"movieName\":\"阿甘正传\",\"isTop\":0,\"rating\":9.5,\"ratingSource\":\"豆瓣\",\"tags\":\"剧情,爱情\",\"synopsis\":\"阿甘于二战结束后不久出生在美国南方阿拉巴马州一个闭塞的小镇，他先天弱智，智商只有75，然而他的妈妈是一个性格坚强的女性。\",\"backdrop\":\"https://picsum.photos/seed/movie3/1280/720\",\"duration\":142}],\"total\":8,\"size\":10,\"current\":1,\"pages\":1},\"success\":true}', 200, 0, 32, NULL, 0, '2026-08-21 11:42:14', '2026-08-21 11:42:14', NULL);
