INSERT INTO `seiko_logs` VALUES (171, 'operation', 'INFO', '查询评论列表', '', 2, 'seiko', '0:0:0:0:0:0:0:1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0', 'GET', 'com.seiko.blog.controller.manage.CommentManageController.getCommentList()', '/api/manage/comment/list', 'page=1&size=10', '{\"code\":200,\"message\":\"操作成功\",\"data\":{\"records\":[{\"id\":10,\"userEmail\":\"wangwu@example.com\",\"author\":\"王五\",\"commentContent\":\"博主加油，文章质量很高。\",\"commentDate\":\"2026-08-16 00:00:00\",\"avatarColor\":\"#DCEDC1\",\"postId\":null,\"createTime\":\"2026-08-16 21:00:00\"},{\"id\":9,\"userEmail\":\"lisi@example.com\",\"author\":\"李四\",\"commentContent\":\"期待 Nginx 那篇草稿完成！\",\"commentDate\":\"2026-08-18 00:00:00\",\"avatarColor\":\"#FFAAA5\",\"postId\":null,\"createTime\":\"2026-08-18 10:00:00\"},{\"id\":8,\"userEmail\":\"zhangsan@example.com\",\"author\":\"张三\",\"commentContent\":\"Java 21 的模式匹配 switch 太香了。\",\"commentDate\":\"2026-08-12 00:00:00\",\"avatarColor\":\"#A8D8EA\",\"postId\":5,\"createTime\":\"2026-08-12 13:10:00\"},{\"id\":7,\"userEmail\":\"zhaoliu@example.com\",\"author\":\"赵六\",\"commentContent\":\"动态规划讲得很清晰，期待更多算法题解。\",\"commentDate\":\"2026-08-15 00:00:00\",\"avatarColor\":\"#FFD3B6\",\"postId\":7,\"createTime\":\"2026-08-15 19:20:00\"},{\"id\":6,\"userEmail\":\"wangwu@example.com\",\"author\":\"王五\",\"commentContent\":\"石家庄的牛肉板面真的好吃，推荐开发区那家。\",\"commentDate\":\"2026-08-13 00:00:00\",\"avatarColor\":\"#DCEDC1\",\"postId\":6,\"createTime\":\"2026-08-13 08:30:00\"},{\"id\":5,\"userEmail\":\"lisi@example.com\",\"author\":\"李四\",\"commentContent\":\"Vue 3 的 ref 和 reactive 终于搞懂了，感谢！\",\"commentDate\":\"2026-08-09 00:00:00\",\"avatarColor\":\"#FFAAA5\",\"postId\":4,\"createTime\":\"2026-08-09 16:45:00\"},{\"id\":4,\"userEmail\":\"zhangsan@example.com\",\"author\":\"张三\",\"commentContent\":\"Docker Compose 部分很实用，已收藏。\",\"commentDate\":\"2026-08-06 00:00:00\",\"avatarColor\":\"#A8D8EA\",\"postId\":3,\"createTime\":\"2026-08-06 11:00:00\"},{\"id\":3,\"userEmail\":\"wangwu@example.com\",\"author\":\"王五\",\"commentContent\":\"MySQL 那篇的延迟关联示例能再补充一下吗？\",\"commentDate\":\"2026-08-05 00:00:00\",\"avatarColor\":\"#DCEDC1\",\"postId\":2,\"createTime\":\"2026-08-05 14:20:00\"},{\"id\":2,\"userEmail\":\"lisi@example.com\",\"author\":\"李四\",\"commentContent\":\"请问虚拟线程在 Tomcat 中怎么配置使用？\",\"commentDate\":\"2026-08-11 00:00:00\",\"avatarColor\":\"#FFAAA5\",\"postId\":5,\"createTime\":\"2026-08-11 09:15:00\"},{\"id\":1,\"userEmail\":\"zhangsan@example.com\",\"author\":\"张三\",\"commentContent\":\"写得很详细，Spring Boot 3 升级后确实流畅很多！\",\"comm', 200, 0, 14, NULL, 0, '2026-08-21 11:43:00', '2026-08-21 11:43:00', NULL);
