ostId\":3,\"createTime\":\"2026-08-06 11:00:00\"},{\"id\":3,\"userEmail\":\"wangwu@example.com\",\"author\":\"王五\",\"commentContent\":\"MySQL 那篇的延迟关联示例能再补充一下吗？\",\"commentDate\":\"2026-08-05 00:00:00\",\"avatarColor\":\"#DCEDC1\",\"postId\":2,\"createTime\":\"2026-08-05 14:20:00\"},{\"id\":2,\"userEmail\":\"lisi@example.com\",\"author\":\"李四\",\"commentContent\":\"请问虚拟线程在 Tomcat 中怎么配置使用？\",\"commentDate\":\"2026-08-11 00:00:00\",\"avatarColor\":\"#FFAAA5\",\"postId\":5,\"createTime\":\"2026-08-11 09:15:00\"},{\"id\":1,\"userEmail\":\"zhangsan@example.com\",\"author\":\"张三\",\"commentContent\":\"写得很详细，Spring Boot 3 升级后确实流畅很多！\",\"comm', 200, 0, 9, NULL, 0, '2026-08-21 11:43:08', '2026-08-21 11:43:08', NULL);
