INSERT INTO `seiko_logs` VALUES (187, 'operation', 'INFO', '查询书籍列表', '', 2, 'seiko', '0:0:0:0:0:0:0:1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0', 'GET', 'com.seiko.blog.controller.manage.BookManageController.getBookList()', '/api/manage/book/list', 'page=1&size=10', '{\"code\":200,\"message\":\"操作成功\",\"data\":{\"records\":[{\"id\":6,\"bookName\":\"活着\",\"bookAuthor\":\"余华\",\"bookCover\":\"https://picsum.photos/seed/book6/200/300\",\"description\":\"讲述一个人和他的命运之间的友情，一部感人至深的中国当代文学经典。\"},{\"id\":5,\"bookName\":\"人类简史\",\"bookAuthor\":\"尤瓦尔·赫拉利\",\"bookCover\":\"https://picsum.photos/seed/book5/200/300\",\"description\":\"从认知革命到科学革命，重新审视人类的过去与未来，开阔视野的佳作。\"},{\"id\":4,\"bookName\":\"高性能 MySQL\",\"bookAuthor\":\"Baron Schwartz\",\"bookCover\":\"https://picsum.photos/seed/book4/200/300\",\"description\":\"MySQL 性能优化的百科全书，涵盖架构、索引、查询优化、复制、高可用等。\"},{\"id\":3,\"bookName\":\"代码整洁之道\",\"bookAuthor\":\"Robert C. Martin\",\"bookCover\":\"https://picsum.photos/seed/book3/200/300\",\"description\":\"讲述编写可读、可维护代码的原则和实践，提升代码质量的必读书。\"},{\"id\":2,\"bookName\":\"设计模式：可复用面向对象软件的基础\",\"bookAuthor\":\"Erich Gamma\",\"bookCover\":\"https://picsum.photos/seed/book2/200/300\",\"description\":\"GoF 四人帮经典著作，23 种设计模式的权威指南，软件工程师必读。\"},{\"id\":1,\"bookName\":\"深入理解计算机系统\",\"bookAuthor\":\"Randal E. Bryant\",\"bookCover\":\"https://picsum.photos/seed/book1/200/300\",\"description\":\"从程序员视角全面剖析计算机系统的经典教材，涵盖数据表示、汇编、存储器层次、链接、异常控制流等核心内容。\"}],\"total\":6,\"size\":10,\"current\":1,\"pages\":1},\"success\":true}', 200, 0, 9, NULL, 0, '2026-08-21 11:43:17', '2026-08-21 11:43:17', NULL);
