INSERT INTO `seiko_logs` VALUES (265, 'operation', 'INFO', '查询文章列表', '', 2, 'seiko', '0:0:0:0:0:0:0:1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', 'GET', 'com.seiko.blog.controller.manage.PostManageController.getPostList()', '/api/manage/post/list', 'page=1&size=100', '{\"code\":200,\"message\":\"操作成功\",\"data\":{\"records\":[{\"id\":7,\"slug\":\"algorithm-dp-basics\",\"title\":\"动态规划入门：从斐波那契到背包问题\",\"excerpt\":\"通过经典题目理解动态规划思想，掌握状态定义、状态转移和空间优化。\",\"content\":\"# 动态规划入门\\n\\n## 核心思想\\n\\n将大问题拆解为子问题，保存子问题的解避免重复计算。\\n\\n## 斐波那契数列\\n\\n```cpp\\nint fib(int n) {\\n    if (n <= 1) return n;\\n    vector<int> dp(n + 1);\\n    dp[0] = 0; dp[1] = 1;\\n    for (int i = 2; i <= n; i++)\\n        dp[i] = dp[i-1] + dp[i-2];\\n    return dp[n];\\n}\\n```\\n\\n## 0-1 背包\\n\\n状态转移: dp[i][j] = max(dp[i-1][j], dp[i-1][j-w[i]] + v[i])\",\"date\":\"2026-08-14\",\"author\":\"Seiko\",\"tags\":[\"算法\"],\"readNum\":678,\"cover\":\"https://picsum.photos/seed/algo/800/400\",\"published\":true},{\"id\":6,\"slug\":\"life-in-shijiazhuang\",\"title\":\"在石家庄工作的日常\",\"excerpt\":\"记录入职以来在石家庄的生活点滴，工作、美食、通勤，平凡而充实。\",\"content\":\"# 在石家庄的日常\\n\\n## 通勤\\n\\n每天早上 7:30 出门，地铁 30 分钟到公司。\\n\\n## 美食推荐\\n\\n- 正定八大碗\\n- 缸炉烧饼\\n- 牛肉板面\\n\\n## 工作节奏\\n\\n朝九晚六，偶尔加班，整体节奏比北京慢一些。\",\"date\":\"2026-08-12\",\"author\":\"Seiko\",\"tags\":[\"生活随笔\"],\"readNum\":432,\"cover\":\"https://picsum.photos/seed/life/800/400\",\"published\":true},{\"id\":5,\"slug\":\"java-21-new-features\",\"title\":\"Java 21 新特性全面解读\",\"excerpt\":\"虚拟线程、模式匹配、记录类、序列集合等 Java 21 重磅新特性详解与实战。\",\"content\":\"# Java 21 新特性\\n\\n## 虚拟线程 (Virtual Threads)\\n\\n```java\\ntry (var executor = Executors.newVirtualThreadPerTaskExecutor()) {\\n    IntStream.range(0, 10000).forEach(i -> executor.submit(() -> {\\n        Thread.sleep(Duration.ofSeconds(1));\\n        return i;\\n    }));\\n}\\n```\\n\\n## 模式匹配 switch\\n\\n```java\\nString format = switch (obj) {\\n    case Integer i -> String.format(\\\"int %d\\\", i);\\n    case String s -> String.format(\\\"string %s\\\", s);\\n    default -> \\\"unknown\\\";\\n};\\n```\",\"date\":\"2026-08-10\",\"author\":\"Seiko\",\"tags\":[\"Java\"],\"readNum\":3102,\"cover\":\"https://picsum.photos/seed/java21/800/400\",\"published\":true},{\"id\":4,\"slug\":\"vue3-composition-api\",\"title\":\"Vue 3 Composition API 深度解析\",\"excerpt\":\"深入理解 Vue 3 的 Composition API，对比 Options API，掌握响应式原理和最佳实践。\",\"content\":\"# Vue 3 Composition API\\n\\n## 为什么需要 Composition API\\n\\n解决大型组件中逻辑复用和代码组织问题。\\n\\n## r', 200, 0, 63, NULL, 0, '2026-08-21 17:00:13', '2026-08-21 17:00:13', NULL);
