INSERT INTO `seiko_logs` VALUES (354, 'login', 'ERROR', '用户登录', '', NULL, NULL, '0:0:0:0:0:0:0:1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0', 'POST', 'com.seiko.blog.controller.manage.UserController.login()', '/api/manage/user/login', NULL, NULL, 500, 1, 39681, '\r\n### Error querying database.  Cause: com.mysql.cj.jdbc.exceptions.CommunicationsException: Communications link failure\n\nThe last packet successfully received from the server was 2,489 milliseconds ago. The last packet sent successfully to the server was 2,489 milliseconds ago.\r\n### The error may exist in com/seiko/blog/mapper/UserMapper.java (best guess)\r\n### The error may involve defaultParameterMap\r\n### The error occurred while setting parameters\r\n### SQL: SELECT  id,username,nickname,email,password_hash,avatar,avatar_color,bio,website,user_role,user_status,last_login_time,create_time,update_time,is_deleted,delete_time  FROM seiko_users  WHERE is_deleted=0     AND (username = ? AND is_deleted = ?)\r\n### Cause: com.mysql.cj.jdbc.exceptions.CommunicationsException: Communications link failure\n\nThe last packet successfully received from the server was 2,489 milliseconds ago. The last packet sent successfully to the server was 2,489 milliseconds ago.\n; Communications link failure\n\nThe last packet successfully received from the server was 2,489 milliseconds ago. The last packet sent successfully to the server was 2,489 milliseconds ago.', 0, '2026-08-24 09:06:11', '2026-08-24 09:06:11', NULL);
