INSERT INTO `seiko_movies` VALUES (1, '肖申克的救赎', 1, 9.7, '豆瓣', '剧情,犯罪,经典', '一场谋杀案使银行家安迪蒙冤入狱，谋杀妻子及其情人的指控将囚禁他终生。在肖申克监狱里，希望似乎虚无缥缈，终身监禁的惩罚无法挽回。', 'https://picsum.photos/seed/movie1/1280/720', 142, 0, '2026-07-29 10:00:00', '2026-08-10 14:00:00', NULL);
INSERT INTO `seiko_movies` VALUES (2, '霸王别姬', 1, 9.6, '豆瓣', '剧情,爱情,同性', '段小楼与程蝶衣是一对打小一起长大的师兄弟，两人一个演生，一个饰旦，一向配合天衣无缝，尤其一出《霸王别姬》，更是誉满京城。', 'https://picsum.photos/seed/movie2/1280/720', 171, 0, '2026-07-29 10:01:00', '2026-07-29 10:01:00', NULL);
INSERT INTO `seiko_movies` VALUES (3, '阿甘正传', 0, 9.5, '豆瓣', '剧情,爱情', '阿甘于二战结束后不久出生在美国南方阿拉巴马州一个闭塞的小镇，他先天弱智，智商只有75，然而他的妈妈是一个性格坚强的女性。', 'https://picsum.photos/seed/movie3/1280/720', 142, 0, '2026-07-29 10:02:00', '2026-07-29 10:02:00', NULL);
INSERT INTO `seiko_movies` VALUES (4, '泰坦尼克号', 0, 9.4, '豆瓣', '剧情,爱情,灾难', '1912年4月10日，号称 \"世界工业史上的奇迹\"的豪华客轮泰坦尼克号开始了自己的处女航，从英国的南安普顿出发驶往美国纽约。', 'https://picsum.photos/seed/movie4/1280/720', 194, 0, '2026-07-29 10:03:00', '2026-07-29 10:03:00', NULL);
INSERT INTO `seiko_movies` VALUES (5, '千与千寻', 1, 9.4, '豆瓣', '剧情,动画,奇幻', '千寻和爸爸妈妈一同驱车前往新家，在郊外的小路上不慎进入了神秘的隧道——他们去到了另外一个诡异世界—一个中世纪的小镇。', 'https://picsum.photos/seed/movie5/1280/720', 125, 0, '2026-07-29 10:04:00', '2026-08-15 09:00:00', NULL);
INSERT INTO `seiko_movies` VALUES (6, '盗梦空间', 0, 9.3, '豆瓣', '剧情,科幻,悬疑', '道姆·柯布与同事阿瑟和纳什在一次针对日本能源大亨齐藤的盗梦行动中失败，反被齐藤利用。', 'https://picsum.photos/seed/movie6/1280/720', 148, 0, '2026-08-01 09:00:00', '2026-08-01 09:00:00', NULL);
INSERT INTO `seiko_movies` VALUES (7, '星际穿越', 0, 9.4, '豆瓣', '剧情,科幻,冒险', '近未来的地球黄沙遍野，小麦、秋葵等基础农作物相继因枯萎病灭绝，人类不再像从前那样仰望星空，放纵想象力和灵感的迸发。', 'https://picsum.photos/seed/movie7/1280/720', 169, 0, '2026-08-03 10:00:00', '2026-08-03 10:00:00', NULL);
INSERT INTO `seiko_movies` VALUES (8, '大话西游之大圣娶亲', 0, 9.2, '豆瓣', '喜剧,爱情,奇幻,古装', '至尊宝被月光宝盒带回到五百年前，遇见紫霞仙子，被对方拔出宝剑，一段感情就此展开。', 'https://picsum.photos/seed/movie8/1280/720', 95, 0, '2026-08-05 14:00:00', '2026-08-05 14:00:00', NULL);
