INSERT INTO `seiko_posts` VALUES (1, 'spring-boot-3-quickstart', 'Spring Boot 3 快速入门指南', '本文介绍 Spring Boot 3 的核心特性与快速搭建方法，包括 Java 21 兼容性、新的配置方式等。', '# Spring Boot 3 快速入门\n\n## 环境准备\n\n- JDK 21+\n- Maven 3.9+\n\n## 创建项目\n\n使用 Spring Initializr 创建项目，选择 Web、JPA、MySQL 依赖。\n\n```java\n@SpringBootApplication\npublic class Application {\n    public static void main(String[] args) {\n        SpringApplication.run(Application.class, args);\n    }\n}\n```\n\n## 配置文件\n\n```yaml\nspring:\n  datasource:\n    url: jdbc:mysql://localhost:3306/seiko_blog\n    username: root\n    password: root\n```\n\n## 总结\n\nSpring Boot 3 带来了更好的性能和现代化的 API，值得升级。', 'https://picsum.photos/seed/springboot/800/400', 'Seiko', 1256, 1, 0, '2026-08-01 09:00:00', '2026-07-30 14:00:00', '2026-08-10 16:30:00', NULL);
INSERT INTO `seiko_posts` VALUES (2, 'mysql-optimization-tips', 'MySQL 性能优化的 10 个实用技巧', '从索引设计、查询优化到配置调优，总结 MySQL 日常开发中最常用的性能优化手段。', '# MySQL 性能优化\n\n## 1. 合理使用索引\n\n为经常出现在 WHERE、JOIN、ORDER BY 中的列创建索引。\n\n## 2. 避免 SELECT *\n\n只查询需要的字段，减少网络传输和内存占用。\n\n## 3. 使用 EXPLAIN 分析\n\n```sql\nEXPLAIN SELECT * FROM seiko_posts WHERE is_published = 1;\n```\n\n## 4. 分页优化\n\n大偏移量分页使用延迟关联。\n\n## 5. 批量操作\n\n批量 INSERT/UPDATE 减少事务开销。', 'https://picsum.photos/seed/mysql/800/400', 'Seiko', 2341, 1, 0, '2026-08-03 10:00:00', '2026-08-01 09:00:00', '2026-08-12 11:20:00', NULL);
INSERT INTO `seiko_posts` VALUES (3, 'docker-deploy-guide', 'Docker 容器化部署完整教程', '从零开始学习 Docker，包括镜像构建、容器编排、Compose 配置以及生产环境部署实践。', '# Docker 部署教程\n\n## Docker 基础\n\nDocker 是一个开源的容器化平台...\n\n## 编写 Dockerfile\n\n```dockerfile\nFROM openjdk:21-jdk-slim\nCOPY target/app.jar /app.jar\nENTRYPOINT [\"java\", \"-jar\", \"/app.jar\"]\n```\n\n## Docker Compose\n\n```yaml\nversion: \"3.8\"\nservices:\n  mysql:\n    image: mysql:8.4\n    environment:\n      MYSQL_ROOT_PASSWORD: root\n  app:\n    build: .\n    ports:\n      - \"8080:8080\"\n```', 'https://picsum.photos/seed/docker/800/400', 'Seiko', 890, 1, 0, '2026-08-05 14:00:00', '2026-08-03 16:00:00', '2026-08-08 09:15:00', NULL);
INSERT INTO `seiko_posts` VALUES (4, 'vue3-composition-api', 'Vue 3 Composition API 深度解析', '深入理解 Vue 3 的 Composition API，对比 Options API，掌握响应式原理和最佳实践。', '# Vue 3 Composition API\n\n## 为什么需要 Composition API\n\n解决大型组件中逻辑复用和代码组织问题。\n\n## ref 与 reactive\n\n```javascript\nimport { ref, reactive } from \"vue\";\n\nconst count = ref(0);\nconst state = reactive({ name: \"Seiko\" });\n```\n\n## 生命周期钩子\n\nonMounted、onUpdated、onUnmounted 等。', 'https://picsum.photos/seed/vue/800/400', 'Seiko', 1567, 1, 0, '2026-08-08 09:30:00', '2026-08-05 11:00:00', '2026-08-15 10:00:00', NULL);
INSERT INTO `seiko_posts` VALUES (5, 'java-21-new-features', 'Java 21 新特性全面解读', '虚拟线程、模式匹配、记录类、序列集合等 Java 21 重磅新特性详解与实战。', '# Java 21 新特性\n\n## 虚拟线程 (Virtual Threads)\n\n```java\ntry (var executor = Executors.newVirtualThreadPerTaskExecutor()) {\n    IntStream.range(0, 10000).forEach(i -> executor.submit(() -> {\n        Thread.sleep(Duration.ofSeconds(1));\n        return i;\n    }));\n}\n```\n\n## 模式匹配 switch\n\n```java\nString format = switch (obj) {\n    case Integer i -> String.format(\"int %d\", i);\n    case String s -> String.format(\"string %s\", s);\n    default -> \"unknown\";\n};\n```', 'https://picsum.photos/seed/java21/800/400', 'Seiko', 3102, 1, 0, '2026-08-10 08:00:00', '2026-08-07 10:00:00', '2026-08-18 14:45:00', NULL);
INSERT INTO `seiko_posts` VALUES (6, 'life-in-shijiazhuang', '在石家庄工作的日常', '记录入职以来在石家庄的生活点滴，工作、美食、通勤，平凡而充实。', '# 在石家庄的日常\n\n## 通勤\n\n每天早上 7:30 出门，地铁 30 分钟到公司。\n\n## 美食推荐\n\n- 正定八大碗\n- 缸炉烧饼\n- 牛肉板面\n\n## 工作节奏\n\n朝九晚六，偶尔加班，整体节奏比北京慢一些。', 'https://picsum.photos/seed/life/800/400', 'Seiko', 432, 1, 0, '2026-08-12 20:00:00', '2026-08-12 19:00:00', '2026-08-12 20:00:00', NULL);
INSERT INTO `seiko_posts` VALUES (7, 'algorithm-dp-basics', '动态规划入门：从斐波那契到背包问题', '通过经典题目理解动态规划思想，掌握状态定义、状态转移和空间优化。', '# 动态规划入门\n\n## 核心思想\n\n将大问题拆解为子问题，保存子问题的解避免重复计算。\n\n## 斐波那契数列\n\n```cpp\nint fib(int n) {\n    if (n <= 1) return n;\n    vector<int> dp(n + 1);\n    dp[0] = 0; dp[1] = 1;\n    for (int i = 2; i <= n; i++)\n        dp[i] = dp[i-1] + dp[i-2];\n    return dp[n];\n}\n```\n\n## 0-1 背包\n\n状态转移: dp[i][j] = max(dp[i-1][j], dp[i-1][j-w[i]] + v[i])', 'https://picsum.photos/seed/algo/800/400', 'Seiko', 678, 1, 0, '2026-08-14 10:30:00', '2026-08-13 15:00:00', '2026-08-16 09:00:00', NULL);
INSERT INTO `seiko_posts` VALUES (8, 'draft-nginx-config', 'Nginx 反向代理配置指南（草稿）', '正在整理 Nginx 反向代理、负载均衡、HTTPS 配置的完整指南，敬请期待。', '# Nginx 配置指南\n\n（草稿中...）\n\n## 反向代理\n\n## 负载均衡\n\n## HTTPS 配置', NULL, 'Seiko', 0, 0, 0, NULL, '2026-08-17 14:00:00', '2026-08-17 14:00:00', NULL);
